-- Gig contracts (#292) shipped without translations (#350).
SET NAMES utf8mb4;

INSERT INTO translations (lang, tkey, value) VALUES
('en','contract_intro','The gig contract for a performance. Date, place, playing time and fee are already on the event — here the wording is added, and you see at a glance where no signed sheet has come back yet.'),
('en','contract_promoter_hint','The contracting party, not the hall. A hall is called "town festival"; it is often booked through an agency — and the agency signs.'),
('en','contract_body_hint','Built from your template when the contract is created, and frozen afterwards: what was sent out must not change because somebody edits the template later. You can still change it here while it is a draft.'),
('en','contract_fee_hint','Can be taken from a quote, otherwise by hand.'),
('en','contract_from_quote','Fee from the quote'),
('en','contract_rebuild','Rebuild from the template'),
('en','contract_rebuild_confirm','Rebuild the wording from the template? Changes of your own will be lost.'),
('en','contract_signed_file','The signed sheet goes to the event as a scan — that is where the files for the performance live.'),
('en','fl_contract_saved','Contract saved.'),
('en','fl_contract_deleted','Contract deleted.'),
('en','fl_contract_status','Status changed: %s.'),
('en','fl_contract_event_required','A contract belongs to an event — pick one.'),
('en','fl_contract_promoter_required','No promoter, no contracting party. A name is enough.'),
('en','set_contract_intro','The wording every new contract is built from. It is yours: change it as your band needs it. As long as nothing stands here, the supplied version applies.'),
('en','set_contract_fields','Placeholders: what stands in curly braces is replaced by the event''s details when the contract is created.'),
('en','set_contract_legal','This is a writing aid, not legal advice. What you sign is your responsibility — when in doubt, have the text looked at by somebody who can judge it.'),
('en','set_contract_reset','Reset to the supplied template'),
('en','set_contract_reset_confirm','Discard your version and take the supplied template?'),
('en','help_vertraege','A performance is agreed by contract, and the program already knows almost everything in it: date, place, playing time and fee are on the event. Here the wording is added, and the list shows for which performance no signed sheet has come back yet.'),
('en','help_vertraege_2','The contracting party is the promoter, not the hall. A hall is called "town festival" and is often booked through an agency — the agency is who signs. That is why there is a list of its own for them.'),
('en','help_vertraege_3','The wording is built from your template when the contract is created, and then stays put. That is deliberate: what was sent and signed must not change because somebody edits the template half a year later. While a contract is a draft you can still change its text.'),
('en','help_vertraege_4','It prints like your other sheets, with logo and watermark. Signed, it comes back as a scan and belongs to the event''s files. Electronic signatures are deliberately absent: they are a subject of their own with requirements of their own, and for a band they bring nothing a scanned sheet does not.'),

('nl','contract_intro','Het optredencontract bij een optreden. Datum, plaats, speeltijd en gage staan al bij de afspraak — hier komt de tekst erbij, en je ziet in één oogopslag waar nog geen ondertekend blad terug is.'),
('nl','contract_promoter_hint','De contractpartij, niet de zaal. Een zaal heet "stadsfeest"; geboekt wordt hij vaak via een bureau — en dat tekent.'),
('nl','contract_body_hint','Bij het aanmaken uit jullie sjabloon opgebouwd en daarna bevroren: wat verstuurd is mag niet veranderen doordat iemand later het sjabloon aanpast. Zolang het een concept is kun je het hier toch wijzigen.'),
('nl','contract_fee_hint','Over te nemen uit een offerte, anders met de hand.'),
('nl','contract_from_quote','Gage uit de offerte'),
('nl','contract_rebuild','Opnieuw opbouwen uit het sjabloon'),
('nl','contract_rebuild_confirm','De tekst opnieuw uit het sjabloon opbouwen? Eigen wijzigingen gaan verloren.'),
('nl','contract_signed_file','Het ondertekende blad gaat als scan naar de afspraak — daar liggen de bestanden van het optreden.'),
('nl','fl_contract_saved','Contract opgeslagen.'),
('nl','fl_contract_deleted','Contract verwijderd.'),
('nl','fl_contract_status','Status gewijzigd: %s.'),
('nl','fl_contract_event_required','Een contract hoort bij een afspraak — kies er een.'),
('nl','fl_contract_promoter_required','Zonder organisator geen contractpartij. Een naam is genoeg.'),
('nl','set_contract_intro','De tekst waaruit elk nieuw contract wordt opgebouwd. Hij is van jullie: pas hem aan zoals jullie band hem nodig heeft. Zolang hier niets staat geldt de meegeleverde versie.'),
('nl','set_contract_fields','Plaatshouders: wat tussen accolades staat wordt bij het aanmaken vervangen door de gegevens van de afspraak.'),
('nl','set_contract_legal','Dit is een schrijfhulp en geen juridisch advies. Wat jullie tekenen is jullie verantwoordelijkheid — laat de tekst bij twijfel eens bekijken door iemand die dat kan beoordelen.'),
('nl','set_contract_reset','Terugzetten op het meegeleverde sjabloon'),
('nl','set_contract_reset_confirm','Jullie versie weggooien en het meegeleverde sjabloon nemen?'),
('nl','help_vertraege','Een optreden wordt per contract afgesproken, en bijna alles wat erin staat kent het programma al: datum, plaats, speeltijd en gage staan bij de afspraak. Hier komt de tekst erbij, en in de lijst zie je bij welk optreden nog geen ondertekend blad terug is.'),
('nl','help_vertraege_2','De contractpartij is de organisator en niet de zaal. Een zaal heet "stadsfeest" en wordt vaak via een bureau geboekt — tekenen doet het bureau. Daarom is er een aparte lijst voor.'),
('nl','help_vertraege_3','De tekst wordt bij het aanmaken uit jullie sjabloon opgebouwd en blijft dan staan. Dat is opzet: wat verstuurd en getekend is mag niet veranderen doordat iemand een half jaar later het sjabloon aanpast. Zolang een contract concept is kun je de tekst toch wijzigen.'),
('nl','help_vertraege_4','Hij wordt gedrukt zoals jullie andere bladen, met logo en watermerk. Getekend komt hij als scan terug en hoort bij de bestanden van de afspraak. Elektronische handtekeningen zijn er bewust niet: dat is een onderwerp apart met eigen eisen, en voor een band leveren ze niets op wat een ingescand blad niet ook levert.'),

('fr','contract_intro','Le contrat de concert pour une prestation. La date, le lieu, la durée de jeu et le cachet figurent déjà sur la date — ici s''ajoute le texte, et vous voyez d''un coup d''œil où aucune feuille signée n''est encore revenue.'),
('fr','contract_promoter_hint','Le cocontractant, pas la salle. Une salle s''appelle « fête de la ville » ; elle est souvent réservée par une agence — et c''est elle qui signe.'),
('fr','contract_body_hint','Composé à partir de votre modèle lors de la création, puis figé : ce qui a été envoyé ne doit pas changer parce que quelqu''un retouche le modèle plus tard. Tant qu''il est à l''état de brouillon, vous pouvez tout de même le modifier ici.'),
('fr','contract_fee_hint','Reprenable depuis un devis, sinon à la main.'),
('fr','contract_from_quote','Cachet tiré du devis'),
('fr','contract_rebuild','Recomposer à partir du modèle'),
('fr','contract_rebuild_confirm','Recomposer le texte à partir du modèle ? Vos propres modifications seront perdues.'),
('fr','contract_signed_file','La feuille signée rejoint la date sous forme de scan — c''est là que se trouvent les fichiers du concert.'),
('fr','fl_contract_saved','Contrat enregistré.'),
('fr','fl_contract_deleted','Contrat supprimé.'),
('fr','fl_contract_status','État modifié : %s.'),
('fr','fl_contract_event_required','Un contrat appartient à une date — choisissez-en une.'),
('fr','fl_contract_promoter_required','Sans organisateur, pas de cocontractant. Le nom suffit.'),
('fr','set_contract_intro','Le texte à partir duquel chaque nouveau contrat est composé. Il est à vous : modifiez-le comme votre groupe en a besoin. Tant que rien n''est écrit ici, la version fournie s''applique.'),
('fr','set_contract_fields','Champs à remplacer : ce qui est entre accolades est remplacé à la création par les informations de la date.'),
('fr','set_contract_legal','Ceci est une aide à la rédaction et non un conseil juridique. Ce que vous signez relève de votre responsabilité — dans le doute, faites relire le texte par quelqu''un qui sait en juger.'),
('fr','set_contract_reset','Revenir au modèle fourni'),
('fr','set_contract_reset_confirm','Abandonner votre version et prendre le modèle fourni ?'),
('fr','help_vertraege','Une prestation se convient par contrat, et le programme connaît déjà presque tout ce qui s''y trouve : date, lieu, durée de jeu et cachet figurent sur la date. Ici s''ajoute le texte, et la liste montre pour quel concert aucune feuille signée n''est encore revenue.'),
('fr','help_vertraege_2','Le cocontractant est l''organisateur et non la salle. Une salle s''appelle « fête de la ville » et se réserve souvent par une agence — c''est l''agence qui signe. D''où une liste à part pour eux.'),
('fr','help_vertraege_3','Le texte est composé à partir de votre modèle lors de la création, puis reste en place. C''est voulu : ce qui a été envoyé et signé ne doit pas changer parce que quelqu''un retouche le modèle six mois plus tard. Tant qu''un contrat est un brouillon, vous pouvez tout de même modifier son texte.'),
('fr','help_vertraege_4','Il s''imprime comme vos autres feuilles, avec logo et filigrane. Signé, il revient en scan et rejoint les fichiers de la date. Les signatures électroniques sont volontairement absentes : c''est un sujet à part avec ses propres exigences, et pour un groupe elles n''apportent rien qu''une feuille scannée n''apporte aussi.'),

('es','contract_intro','El contrato de actuación para un concierto. La fecha, el lugar, el tiempo de actuación y el caché ya están en la cita — aquí se añade el texto, y de un vistazo veis dónde todavía no ha vuelto ninguna hoja firmada.'),
('es','contract_promoter_hint','La parte contratante, no la sala. Una sala se llama "fiesta mayor"; a menudo se contrata a través de una agencia — y esa es la que firma.'),
('es','contract_body_hint','Se compone de vuestra plantilla al crearlo y después queda congelado: lo que se envió no debe cambiar porque alguien toque la plantilla más tarde. Mientras sea borrador podéis cambiarlo aquí igualmente.'),
('es','contract_fee_hint','Se puede tomar de un presupuesto, si no, a mano.'),
('es','contract_from_quote','Caché del presupuesto'),
('es','contract_rebuild','Volver a componer desde la plantilla'),
('es','contract_rebuild_confirm','¿Volver a componer el texto desde la plantilla? Los cambios propios se perderán.'),
('es','contract_signed_file','La hoja firmada llega a la cita como escaneo — allí están los archivos del concierto.'),
('es','fl_contract_saved','Contrato guardado.'),
('es','fl_contract_deleted','Contrato eliminado.'),
('es','fl_contract_status','Estado cambiado: %s.'),
('es','fl_contract_event_required','Un contrato pertenece a una cita — elige una.'),
('es','fl_contract_promoter_required','Sin organizador no hay parte contratante. Basta con el nombre.'),
('es','set_contract_intro','El texto con el que se compone cada contrato nuevo. Es vuestro: cambiadlo como lo necesite vuestra banda. Mientras aquí no haya nada, rige la versión incluida.'),
('es','set_contract_fields','Marcadores: lo que está entre llaves se sustituye al crearlo por los datos de la cita.'),
('es','set_contract_legal','Esto es una ayuda de redacción, no asesoramiento jurídico. De lo que firmáis respondéis vosotros — en caso de duda, que lo lea alguien que sepa valorarlo.'),
('es','set_contract_reset','Restablecer a la plantilla incluida'),
('es','set_contract_reset_confirm','¿Descartar vuestra versión y tomar la plantilla incluida?'),
('es','help_vertraege','Un concierto se acuerda por contrato, y casi todo lo que hay en él ya lo conoce el programa: fecha, lugar, tiempo de actuación y caché están en la cita. Aquí se añade el texto, y en la lista veis en qué concierto todavía no ha vuelto una hoja firmada.'),
('es','help_vertraege_2','La parte contratante es el organizador y no la sala. Una sala se llama "fiesta mayor" y a menudo se contrata a través de una agencia — quien firma es la agencia. Por eso hay una lista propia para ellos.'),
('es','help_vertraege_3','El texto se compone de vuestra plantilla al crear el contrato y luego se queda como está. Es a propósito: lo que se envió y se firmó no debe cambiar porque alguien toque la plantilla medio año después. Mientras un contrato sea borrador podéis cambiar su texto igualmente.'),
('es','help_vertraege_4','Se imprime como vuestras otras hojas, con logotipo y marca de agua. Firmado vuelve como escaneo y pertenece a los archivos de la cita. Las firmas electrónicas no están aquí a propósito: son un asunto aparte con requisitos propios, y a una banda no le aportan nada que no aporte también una hoja escaneada.'),

('it','contract_intro','Il contratto per un concerto. Data, luogo, durata e compenso sono già sull''appuntamento — qui si aggiunge il testo, e si vede a colpo d''occhio dove non è ancora tornato alcun foglio firmato.'),
('it','contract_promoter_hint','La controparte, non la sala. Una sala si chiama "festa cittadina"; spesso viene scritturata tramite un''agenzia — ed è quella che firma.'),
('it','contract_body_hint','Composto dal vostro modello alla creazione e poi congelato: ciò che è stato inviato non deve cambiare perché qualcuno ritocca il modello più tardi. Finché è una bozza potete comunque modificarlo qui.'),
('it','contract_fee_hint','Si può riprendere da un preventivo, altrimenti a mano.'),
('it','contract_from_quote','Compenso dal preventivo'),
('it','contract_rebuild','Ricomporre dal modello'),
('it','contract_rebuild_confirm','Ricomporre il testo dal modello? Le modifiche proprie andranno perse.'),
('it','contract_signed_file','Il foglio firmato arriva all''appuntamento come scansione — lì stanno i file del concerto.'),
('it','fl_contract_saved','Contratto salvato.'),
('it','fl_contract_deleted','Contratto eliminato.'),
('it','fl_contract_status','Stato cambiato: %s.'),
('it','fl_contract_event_required','Un contratto appartiene a un appuntamento — scegline uno.'),
('it','fl_contract_promoter_required','Senza organizzatore non c''è controparte. Basta il nome.'),
('it','set_contract_intro','Il testo da cui viene composto ogni nuovo contratto. È vostro: cambiatelo come serve alla vostra band. Finché qui non c''è nulla vale la versione fornita.'),
('it','set_contract_fields','Segnaposto: quello che sta tra parentesi graffe viene sostituito alla creazione con i dati dell''appuntamento.'),
('it','set_contract_legal','Questo è un aiuto alla scrittura e non una consulenza legale. Di ciò che firmate rispondete voi — nel dubbio fate leggere il testo a qualcuno in grado di valutarlo.'),
('it','set_contract_reset','Riportare al modello fornito'),
('it','set_contract_reset_confirm','Scartare la vostra versione e prendere il modello fornito?'),
('it','help_vertraege','Un concerto si concorda per contratto, e quasi tutto ciò che vi sta dentro il programma lo conosce già: data, luogo, durata e compenso stanno sull''appuntamento. Qui si aggiunge il testo, e nell''elenco vedete per quale concerto non è ancora tornato un foglio firmato.'),
('it','help_vertraege_2','La controparte è l''organizzatore e non la sala. Una sala si chiama "festa cittadina" e spesso viene scritturata tramite un''agenzia — a firmare è l''agenzia. Per questo c''è un elenco a parte.'),
('it','help_vertraege_3','Il testo viene composto dal vostro modello alla creazione e poi resta com''è. È voluto: ciò che è stato inviato e firmato non deve cambiare perché qualcuno ritocca il modello sei mesi dopo. Finché un contratto è una bozza potete comunque cambiarne il testo.'),
('it','help_vertraege_4','Si stampa come gli altri vostri fogli, con logo e filigrana. Firmato torna come scansione e appartiene ai file dell''appuntamento. Le firme elettroniche qui non ci sono di proposito: sono un tema a sé con requisiti propri, e a una band non portano nulla che non porti anche un foglio scansionato.')
ON DUPLICATE KEY UPDATE value = value;
